import heapq
from itertools import combinations


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    initial_mask = sum(1 << i for i, node in enumerate(required)
                       if node == data["source"])
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    start_state = (data["source"], initial_mask, 0)
    best = {start_state: start}
    queue = [(start, data["source"], initial_mask, 0)]
    coupons = data["coupons"]
    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full and
                (coupon_rule == "at_most" or used == coupons)):
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask
                for i, required_node in enumerate(required):
                    if required_node == next_node:
                        next_mask |= 1 << i
                next_state = (next_node, next_mask, next_used)
                if next_time < best.get(next_state, float("inf")):
                    best[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask,
                                           next_used))
    return {"arrival": None}


def _component_01(data):
    return _route(data, "at_most", 1)


def _component_02(data):
    return _route(data, "exact", 1)


def _component_03(data):
    return _route(data, "at_most", 2)


def _component_04(data):
    return _route(data, "exact", 2)


def _component_05(data):
    return _route(data, "at_most", 1)


def _rounded(numerator, denominator, mode):
    quotient, remainder = divmod(numerator, denominator)
    if mode == "half_up" and 2 * remainder >= denominator:
        quotient += 1
    return quotient


def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _rounded(raw * (10000 - discount), 10000, mode)
        tax = _rounded(net * event.get("tax_bp", 0), 10000, mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _component_07(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
    best_vector = None
    best_versions = None

    def visit(assigned, constraints, graph):
        nonlocal best_vector, best_versions
        pending = [name for name in constraints if name not in assigned]
        if not pending:
            # Reject cycles, including self-loops.
            active, done = set(), set()

            def acyclic(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for child in graph.get(name, ()):
                    if not acyclic(child):
                        return False
                active.remove(name)
                done.add(name)
                return True

            if not all(acyclic(name) for name in assigned):
                return
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_versions = dict(assigned)
            return

        name = min(pending)
        low = max(interval[0] for interval in constraints[name])
        high = min(interval[1] for interval in constraints[name])
        if name in pins:
            low = max(low, pins[name])
            high = min(high, pins[name])
        rows = sorted(packages.get(name, []), key=lambda row: row["version"])
        for row in rows:
            version = row["version"]
            if (not low <= version <= high or
                    version in blocked.get(name, [])):
                continue
            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_constraints = {key: list(value)
                                for key, value in constraints.items()}
            next_graph = {key: list(value) for key, value in graph.items()}
            deps = [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]
            valid = True
            children = []
            for dep in deps:
                child = dep["name"]
                interval = (dep["min"], dep["max"])
                next_constraints.setdefault(child, []).append(interval)
                children.append(child)
                if child in next_assigned and not interval[0] <= next_assigned[child] <= interval[1]:
                    valid = False
                    break
            if not valid:
                continue
            next_graph[name] = children
            visit(next_assigned, next_constraints, next_graph)

    visit({}, roots, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _component_08(data):
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    options = [job for job in data["jobs"] if job["id"] not in blocked]
    if not mandatory.issubset({job["id"] for job in options}):
        return {"error": "impossible"}
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for group in combinations(options, k):
        ids = tuple(sorted(job["id"] for job in group))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in group:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(name, 0) <= high
               for name, (low, high) in quotas.items()):
            continue
        ordered = sorted(group, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in group)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


SOLVERS = {
    "component_01": _component_01,
    "component_02": _component_02,
    "component_03": _component_03,
    "component_04": _component_04,
    "component_05": _component_05,
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}

