def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    versions = {}
    for name in names:
        versions[name] = [None] + sorted(
            row["version"] for row in packages[name]
            if row["version"] not in blocked.get(name, []) and
            (name not in pins or row["version"] == pins[name]))

    best_vector = None
    best = None
    for values in product(*(versions[name] for name in names)):
        installed = dict(zip(names, values))
        if any(installed.get(name) is None or
               not bounds[0] <= installed[name] <= bounds[1]
               for name, bounds in data["roots"].items()):
            continue

        rows = {}
        for name, version in installed.items():
            if version is not None:
                rows[name] = next(row for row in packages[name]
                                  if row["version"] == version)

        edges = {name: [] for name in rows}
        valid = True
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                version = installed.get(target)
                if version is None or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(rows):
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            state[name] = 2
            return True
        if not all(visit(name) for name in rows):
            continue

        vector = tuple(installed[name] if installed[name] is not None else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = {name: installed[name] for name in names
                    if installed[name] is not None}
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _routes(data):
    import heapq

    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    start_state = (data["source"], initial_mask, 0)
    distances = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, 0)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and used == data["coupons"]:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            next_mask = mask | bit.get(edge["v"], 0)
            choices = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, used + 1))
            for duration, next_used in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, *next_state))
    return {"arrival": None}


