def _component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit_for.get(source, 0)
        initial = (source, data["coupons"], initial_mask)
        start = data["start"]
        distances = {initial: start}
        queue = [(start, source, data["coupons"], initial_mask)]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, remaining, mask = heapq.heappop(queue)
            state = (node, remaining, mask)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and time <= data["deadline"]:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [(edge["duration"], remaining)]
                if remaining:
                    durations.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
                next_mask = mask | bit_for.get(edge["v"], 0)
                for duration, next_remaining in durations:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_remaining, next_mask)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, edge["v"], next_remaining, next_mask))
        return {"arrival": None}
    return solve


