        ends = []
        overlap_ok = True
        for job in sorted(chosen, key=lambda j: (j["start"], j["end"], j["id"])):
            while ends and ends[0] <= job["start"]:
                heapq.heappop(ends)
            heapq.heappush(ends, job["end"])
            if len(ends) > 2:
                overlap_ok = False
                break
        if not overlap_ok:
