    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    domains = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, [])
                          and (name not in pins or row["version"] == pins[name]))
        domains.append([-1] + versions)

    for values in product(*domains):
        chosen = dict(zip(names, values))
        installed = {n for n, v in chosen.items() if v != -1}
        constraints = {n: [] for n in packages}
        for name, bounds in data["roots"].items():
            constraints[name].append(tuple(bounds))

        edges = {n: [] for n in packages}
        reachable = set()
        pending = list(data["roots"])
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            version = chosen[name]
            if version == -1 or any(not lo <= version <= hi
                                    for lo, hi in constraints[name]):
                valid = False
                break
            row = next(r for r in packages[name] if r["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                lo, hi = dep["min"], dep["max"]
                constraints[other].append((lo, hi))
                edges[name].append(other)
                pending.append(other)
        if not valid or reachable != installed:
            continue

        state = {}
        def acyclic(node):
            if state.get(node) == 1:
                return False
            if state.get(node) == 2:
                return True
            state[node] = 1
            if any(not acyclic(other) for other in edges[node]):
                return False
            state[node] = 2
            return True

        if all(acyclic(n) for n in reachable):
            return {"versions": {n: chosen[n] for n in packages if n in installed}}
    return {"error": "unsatisfiable"}


