    best_ids = None
    available = [job for job in jobs if job["id"] not in blocked]
    for subset in combinations(available, k):
        ids = sorted(job["id"] for job in subset)
        idset = set(ids)
        if not mandatory.issubset(idset):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in subset:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        feasible = True
        for _, delta in sorted(events):
            active += delta
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue
        value = sum(job["value"] for job in subset)
        if best_value is None or value > best_value or (value == best_value and ids < best_ids):
            best_value, best_ids = value, ids
    if best_value is None:
