                closure.add(name)
                todo.extend(edges.get(name, []))
            if closure != installed:
                continue

            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                for other in edges.get(name, []):
                    if not visit(other):
                        return False
                state[name] = 2
                return True
            if not all(visit(name) for name in installed):
                continue

            vector = tuple(selected[name] for name in order)
            if best_vector is None or (vector > best_vector if want_max else vector < best_vector):
                best_vector = vector
