from itertools import combinations, product
import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None
        for subset in combinations([j for j in jobs if j["id"] not in blocked], k):
            ids = {j["id"] for j in subset}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not lo <= counts.get(group, 0) <= hi
                   for group, (lo, hi) in quotas.items()):
                continue
            active = []
            valid = True
            for job in sorted(subset, key=lambda j: (j["start"], j["end"])):
                while active and active[0] <= job["start"]:
                    heapq.heappop(active)
                heapq.heappush(active, job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            selected = sorted(ids)
            value = sum(j["value"] for j in subset)
            if (best_ids is None or value > best_value or
                    (value == best_value and
                     (selected < best_ids if tie == "smallest" else selected > best_ids))):
                best_ids, best_value = selected, value
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        eid = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if eid not in winners or key > winners[eid][0]:
            winners[eid] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d=10000):
        if mode == "half_up":
            return (2 * n + d) // (2 * d)
        return n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data.get("roots", {})
    rows = {name: {r["version"]: r for r in packages[name]} for name in names}
    choices = []
    for name in names:
        allowed = sorted(v for v in rows[name]
                         if v not in blocked.get(name, []) and
                         (name not in pins or v == pins[name]))
        choices.append([-1] + allowed)

    for values in product(*choices):
        selected = {name: version for name, version in zip(names, values) if version != -1}
        good = True
        for name, (lo, hi) in roots.items():
            if name not in selected or not lo <= selected[name] <= hi:
                good = False
                break
        if not good:
            continue
        edges = {name: [] for name in selected}
        for name, version in selected.items():
            row = rows[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                child = dep["name"]
                if child not in selected or not dep["min"] <= selected[child] <= dep["max"]:
                    good = False
                    break
                edges[name].append(child)
            if not good:
                break
        if not good:
            continue
        # Installed packages must be precisely the dependency closure of roots.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in selected:
                good = False
                break
            reachable.add(name)
            stack.extend(edges[name])
        if not good or reachable != set(selected):
            continue
        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(child) for child in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in selected):
            continue
        return {"versions": selected}
    return {"error": "unsatisfiable"}


def _routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    initial_mask = bit.get(start_node, 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    initial = (start_node, initial_mask, data["coupons"])
    best = {initial: data["start"]}
    queue = [(data["start"], start_node, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if best.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [edge["duration"]]
            if coupons:
                durations.append(max(2, edge["duration"] - edge.get("discount", 0)))
            for index, duration in enumerate(durations):
                remaining = coupons - (1 if index == 1 else 0)
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, remaining)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, remaining))
    return {"arrival": None}


