def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        # Enumerating version-or-absent vectors in sorted lexicographic order
        # directly implements the specified global tie-break.
        choices = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name])
            choices.append([-1] + versions)

        for vector in product(*choices):
            installed = {name: version for name, version in zip(names, vector)
                         if version != -1}
            if any(name not in installed for name in roots):
                continue
            if any(name in installed and installed[name] in blocked.get(name, [])
                   for name in names):
                continue
            if any(name in installed and installed[name] != version
                   for name, version in pins.items()):
                continue

            rows_by_name = {}
            for name, version in installed.items():
                rows_by_name[name] = next((row for row in packages[name]
                                           if row["version"] == version), None)
            edges = {name: [] for name in installed}
            valid = True
            for name, row in rows_by_name.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    version = installed.get(other)
                    if version is None or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            # Every selected package must belong to the active closure of roots.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges[name])
            if reachable != set(installed):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if all(visit(name) for name in installed):
                return {"versions": installed}
        return {"error": "unsatisfiable"}
    return solve


