        pins = data.get("pins", {})
        rows_by_version = {
            name: {row["version"]: row for row in rows}
            for name, rows in packages.items()
        }
        choices = [[-1] + sorted(rows_by_version[name]) for name in names]

        for vector in product(*choices):
            installed = {name: version for name, version in zip(names, vector)
                         if version != -1}
            if any(name not in installed or
                   not bounds[0] <= installed[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue
            if any(version in blocked.get(name, [])
                   for name, version in installed.items()):
                continue
            if any(name in installed and installed[name] != version
                   for name, version in pins.items()):
                continue

            edges = {name: [] for name in installed}
            valid = True
            for name, version in installed.items():
                row = rows_by_version[name][version]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    other_version = installed.get(other)
                    if (other_version is None or
                            not dep["min"] <= other_version <= dep["max"]):
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

