            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges[name])
            if reachable != set(installed):
                continue

            finished, active = set(), set()

            def acyclic(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                for other in edges[name]:
                    if not acyclic(other):
                        return False
                active.remove(name)
                finished.add(name)
                return True

            if all(acyclic(name) for name in installed):
                return {"versions": installed}
        return {"error": "unsatisfiable"}
    return solve


